#!/bin/sh
# SPDX-FileCopyrightText: The Gommitlint Authors
#
# SPDX-License-Identifier: EUPL-1.2 OR GPL-3.0-or-later
#
# gommitlint commit-msg hook for validating commit messages.
# Generated by gommitlint hook install command.
#
# To bypass this hook in emergencies:
#   git commit --no-verify
#
# Environment variables:
#   GOMMITLINT_DEBUG=1            Enable debug output
#   NO_COLOR=1                    Disable colored output
#   GOMMITLINT_HOOK_MISSING=skip  Allow the operation when gommitlint is not installed
#

set -e

# Get the commit message file path
COMMIT_MSG_FILE=$1

# Resolve the linter: PATH first, then the binary that installed this hook
# (substituted at install time), so GUI clients and shells without the
# developer's PATH still validate. A hook that enforces policy must not pass
# when its tool is absent, so a missing linter fails the commit-msg with guidance.
# Set GOMMITLINT_HOOK_MISSING=skip to allow it through unvalidated instead.
GOMMITLINT_INSTALLED_BIN="@GOMMITLINT_INSTALLED_BIN@"
if command -v gommitlint >/dev/null 2>&1; then
  GOMMITLINT=gommitlint
elif [ -n "$GOMMITLINT_INSTALLED_BIN" ] && [ -x "$GOMMITLINT_INSTALLED_BIN" ]; then
  GOMMITLINT=$GOMMITLINT_INSTALLED_BIN
elif [ "${GOMMITLINT_HOOK_MISSING:-}" = "skip" ]; then
  printf "• [gommitlint] not found in PATH; skipping commit-msg validation (GOMMITLINT_HOOK_MISSING=skip)\n" >&2
  exit 0
else
  printf "✗ [gommitlint] gommitlint not found in PATH; refusing to commit unvalidated\n" >&2
  printf "  Install it: https://codefloe.com/itiquette/gommitlint#installation\n" >&2
  printf "  Or allow this once: GOMMITLINT_HOOK_MISSING=skip git commit ...\n" >&2
  printf "  Or bypass hooks entirely: git commit --no-verify\n" >&2
  exit 1
fi

# gommitlint:shared-body-begin commit-msg
# Lines below this marker MUST stay byte-identical between standalone and plugin
# variants. The drift test in scripts/hooks/embed_test.go enforces this.
FLAGS=""

# Handle color output
if [ -n "$NO_COLOR" ] || [ ! -t 2 ]; then
  FLAGS="$FLAGS --color=never"
fi

# Handle debug mode
if [ -n "$GOMMITLINT_DEBUG" ]; then
  FLAGS="$FLAGS --log-level=debug"
fi

# Capture stdout for failure reporting while leaving warnings and debug logs on stderr.
# shellcheck disable=SC2086
if OUTPUT=$("$GOMMITLINT" validate --message-file="$COMMIT_MSG_FILE" --exclude-rule cryptosignature $FLAGS); then
  EXIT_CODE=0
else
  EXIT_CODE=$?
fi

if [ "$EXIT_CODE" -eq 0 ]; then
  printf "[gommitlint] ✓ commit-msg passed\n" >&2
  exit 0
else
  printf "✗ [gommitlint] commit-msg failed\n\n" >&2
  printf "%s\n" "$OUTPUT" >&2
  printf "\n\nOptions:\n" >&2
  printf "  - Fix the issues above and try again\n" >&2
  printf "  - Run 'gommitlint config show' to see active rules\n" >&2
  printf "  - Use 'git commit --no-verify' to bypass (not recommended)\n" >&2
  exit "$EXIT_CODE"
fi
